					if (outcome.kind === "error") throw new Error(`AnalysisRecord 保存失败: ${outcome.message}`);
					const saved = parseJson(outcome.text, "保存产物", (value) => value !== null && typeof value === "object");
					assertRecordShape(saved);
					return saved;
